const ExcelJS = require('exceljs');

async function main() {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Flights');

  // Define columns
  sheet.columns = [
    { header: 'Flight Number', key: 'flightNumber', width: 15 },
    { header: 'From',          key: 'from',         width: 10 },
    { header: 'To',            key: 'to',           width: 10 },
    { header: 'Date',          key: 'date',         width: 15 },
    { header: 'Departure Time',key: 'time',         width: 18 },
  ];

  // Bold the header row
  sheet.getRow(1).font = { bold: true };

  // Add the flight record
  sheet.addRow({
    flightNumber: 'FL6BD665',
    from: 'LAX',
    to: 'SFO',
    date: '2026-09-05',
    time: '09:00',
  });

  await workbook.xlsx.writeFile('skills/OfficeBench/testbed/data/travel_expenses.xlsx');
  console.log('File created successfully!');
}

main().catch(console.error);
"

